create or replace function public._academic_stage_key(_n text) returns text language sql immutable set search_path=public as $$ select regexp_replace(trim(coalesce(_n,'')), '^المرحلة\s+', '') $$;
create or replace function public._academic_grade_guard() returns trigger language plpgsql set search_path=public as $$ declare st text; begin select name into st from stages where id=new.stage_id and school_id=new.school_id; if st is null then raise exception 'المرحلة ليست في الفرع'; end if; if tg_op='INSERT' or (new.name,new.stage_id) is distinct from (old.name,old.stage_id) then if not exists(select 1 from academic_catalog where kind='grade' and name=new.name and _academic_stage_key(stage)=_academic_stage_key(st)) and not exists(select 1 from org_academic_catalog where org_id=school_org(new.school_id) and kind='grade' and name=new.name and _academic_stage_key(stage)=_academic_stage_key(st)) then raise exception 'الصف غير معتمد لهذه المرحلة'; end if; end if; return new; end $$;